WITH ops AS (SELECT o.operation_id,s.service_code FROM logical_operations o JOIN service_routes r USING(route_id) JOIN services s USING(service_id) WHERE o.opened_at_ms>=1777629600000 AND o.opened_at_ms<1777633200000), stats AS (SELECT ops.operation_id,ops.service_code,count(a.attempt_id) attempts,sum(CASE WHEN f.is_success=0 THEN 1 ELSE 0 END) failed_attempts,max(a.attempt_no) max_no,max(CASE WHEN a.attempt_no=(SELECT max(a2.attempt_no) FROM attempt_events a2 WHERE a2.operation_id=ops.operation_id) THEN f.is_success END) final_success FROM ops LEFT JOIN attempt_events a USING(operation_id) LEFT JOIN failure_codes f USING(code_id) GROUP BY ops.operation_id) SELECT service_code,count(*) operations,sum(attempts) attempts,sum(failed_attempts) failed_attempts,sum(final_success=0) terminal_failures,sum(max_no>1) retried FROM stats GROUP BY service_code;
WITH ops AS (SELECT o.operation_id,o.route_id,s.service_code,o.opened_at_ms FROM logical_operations o JOIN service_routes r USING(route_id) JOIN services s USING(service_id) WHERE o.opened_at_ms>=1777629600000 AND o.opened_at_ms<1777633200000) SELECT service_code,count(distinct a.pool_id) pools FROM ops JOIN route_assignments a ON a.route_id=ops.route_id AND ops.opened_at_ms>=a.effective_from_ms AND ops.opened_at_ms<a.effective_to_ms GROUP BY service_code;
SQL

